package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	scanner.Scan()
	d, _ := strconv.Atoi(scanner.Text())
	_ = d

	scanner.Scan()
	ab := scanner.Text()

	k := 0
	y := 0

	for i := 0; i < len(ab); i++ {
		k += int(ab[i]) - 48
	}

	for i := 2; i <= k; i++ {
		cc := 0
		if k%i == 0 {
			c := 0
			for ii := 0; ii < len(ab); ii++ {
				c += int(ab[ii]) - 48
				if c == k/i {
					c = 0
					cc++
				}
				if c > k/i {
					break
				}
			}
		}
		if cc == i {
			fmt.Fprintln(writer, "YES")
			y = 1
			break
		}
	}

	if k == 0 {
		fmt.Fprintln(writer, "YES")
	}
	if y == 0 && k != 0 {
		fmt.Fprintln(writer, "NO")
	}
}

